def normalize_to_chatml(record):
    messages = []
    if 'instruction' in record and 'output' in record:
        if record.get('input', '').strip():
            content = f"{record['instruction']}\n\nInput:\n{record['input']}"
        else:
            content = record['instruction']
        messages.append({'role': 'user', 'content': content})
        messages.append({'role': 'assistant', 'content': record['output']})
    elif 'conversations' in record:
        role_map = {'human': 'user', 'gpt': 'assistant', 'system': 'system'}
        for turn in record['conversations']:
            messages.append({'role': role_map.get(turn['from'], turn['from']), 'content': turn['value']})
    return messages

