def truncate_dialogue(messages, max_tokens, tokenizer):
    system_msg = [m for m in messages if m['role'] == 'system']
    history = [m for m in messages if m['role'] != 'system']
    while True:
        candidate = system_msg + history
        rendered = tokenizer.apply_chat_template(candidate, tokenize=False)
        tokens = tokenizer.encode(rendered)
        if len(tokens) <= max_tokens or len(history) < 2:
            return candidate
        history = history[2:]

day-61-act-04.answer:
class ChatMLDatasetValidator:
    def __init__(self, tokenizer):
        self.tokenizer = tokenizer
    def validate_record(self, messages):
        if not messages:
            return False, 'Empty messages'
        roles = [m['role'] for m in messages]
        if roles[0] == 'system':
            turns = roles[1:]
        else:
            turns = roles
        if not turns or turns[0] != 'user' or turns[-1] != 'assistant':
            return False, 'Must start with user and end with assistant'
        for i in range(1, len(turns)):
            if turns[i] == turns[i-1]:
                return False, f'Consecutive duplicate role: {turns[i]}'
        return True, 'Valid'
    def process_batch(self, batch):
        valid, filtered = [], []
        for item in batch:
            ok, reason = self.validate_record(item)
            if ok:
                valid.append(item)
            else:
                filtered.append((item, reason))
        return valid, filtered
